typedef struct {
    int width;
    int height;
    const unsigned char* data;
    unsigned int size;
} IconResource;

static const IconResource g_IconResources[] = {
    { 16, 16, g_IconData_0_16x16, sizeof(g_IconData_0_16x16) },
    { 16, 16, g_IconData_1_16x16, sizeof(g_IconData_1_16x16) },
    { 24, 24, g_IconData_2_24x24, sizeof(g_IconData_2_24x24) },
    { 32, 32, g_IconData_3_32x32, sizeof(g_IconData_3_32x32) },
    { 64, 64, g_IconData_4_64x64, sizeof(g_IconData_4_64x64) },
};

const int g_IconImageCount = 5;


/* ---------------------------------------------------------------------
 * Original functions without DPI support
 * ------------------------------------------------------------------- */


HICON IconGetByIndex(int index)
{
    if (index < 0 || index >= g_IconImageCount)
        return NULL;

    const IconResource* res = &g_IconResources[index];
    return CreateIconFromResourceEx(
        (PBYTE)res->data,
        res->size,
        TRUE,           /* fIcon: TRUE = icon, FALSE = cursor */
        0x00030000,     /* resource version, per MSDN */
        res->width,
        res->height,
        LR_DEFAULTCOLOR);
}

HICON IconGetBySize(int size)
{
    for (int i = 0; i < g_IconImageCount; i++) {
        if (g_IconResources[i].width == size &&
            g_IconResources[i].height == size) {
            return IconGetByIndex(i);
        }
    }
    return NULL;
}

/* ---------------------------------------------------------------------
 * DPI-aware loading
 *
 * The functions above always hand back an icon at its native pixel size
 * (16, 24, 32, or 64). That's fine at 96 DPI (100% scaling), but once the
 * process is per-monitor DPI aware (DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2)
 * a "16px" icon needs to be rendered larger on a high-DPI monitor or it
 * will look tiny. The functions below scale a *logical* size (the size
 * you'd ask for at 100%, e.g. 16 for a toolbar icon) up to the correct
 * physical pixel size for a given DPI, pick the best source bitmap to
 * scale from, and let CreateIconFromResourceEx do the resampling.
 * ------------------------------------------------------------------- */

 /* Picks the best source image index to scale from for a desired pixel
  * size. Prefers the smallest available image that is >= desiredSize
  * (scaling down looks better than scaling up); falls back to the
  * largest available image if desiredSize exceeds everything we have. */
static int IconPickBestIndexForSize(int desiredSize)
{
    int bestIndex = -1;
    int bestDelta = INT_MAX;
    int largestIndex = -1;
    int largestSize = -1;

    for (int i = 0; i < g_IconImageCount; i++) {
        int sz = g_IconResources[i].width; /* icons are square */

        if (sz == desiredSize)
            return i; /* exact match, nothing to scale */

        if (sz > desiredSize && (sz - desiredSize) < bestDelta) {
            bestDelta = sz - desiredSize;
            bestIndex = i;
        }

        if (sz > largestSize) {
            largestSize = sz;
            largestIndex = i;
        }
    }

    return (bestIndex != -1) ? bestIndex : largestIndex;
}

/* Loads a specific source image, scaled to an explicit pixel size. */
HICON IconGetByIndexForSize(int index, int desiredSize)
{
    if (index < 0 || index >= g_IconImageCount || desiredSize <= 0)
        return NULL;

    const IconResource* res = &g_IconResources[index];
    return CreateIconFromResourceEx(
        (PBYTE)res->data,
        res->size,
        TRUE,           /* fIcon: TRUE = icon, FALSE = cursor */
        0x00030000,     /* resource version, per MSDN */
        desiredSize,
        desiredSize,
        LR_DEFAULTCOLOR);
}

/* Loads the icon closest to baseSize (a logical, 96-DPI size, e.g. 16
 * for a toolbar icon) scaled to match the given DPI. */
HICON IconGetBySizeForDpi(int baseSize, UINT dpi)
{
    if (dpi == 0)
        dpi = USER_DEFAULT_SCREEN_DPI;

    int desiredSize = MulDiv(baseSize, (int)dpi, USER_DEFAULT_SCREEN_DPI);
    int index = IconPickBestIndexForSize(desiredSize);
    if (index < 0)
        return NULL;

    return IconGetByIndexForSize(index, desiredSize);
}

/* Convenience wrapper: reads the DPI directly from a window. Call this
 * from WM_CREATE and again from WM_DPICHANGED so icons stay crisp when
 * the window moves between monitors with different scaling. Requires
 * Windows 10 1607+ (same era as DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2). */
HICON IconGetBySizeForWindow(int baseSize, HWND hwnd)
{
    UINT dpi = hwnd ? GetDpiForWindow(hwnd) : USER_DEFAULT_SCREEN_DPI;
    return IconGetBySizeForDpi(baseSize, dpi);
}


/* Invert icon. */

HICON IconWhiteToBlack(HICON hIcon)
{
    ICONINFO iconInfo;
    if (!GetIconInfo(hIcon, &iconInfo))
        return NULL;

    // Get bitmap info for the color mask
    BITMAP bmColor;
    GetObject(iconInfo.hbmColor, sizeof(BITMAP), &bmColor);

    int width = bmColor.bmWidth;
    int height = bmColor.bmHeight;

    // Set up a 32-bit BGRA DIB so we can read/write pixels directly
    BITMAPINFO bmi = { 0 };
    bmi.bmiHeader.biSize = sizeof(BITMAPINFOHEADER);
    bmi.bmiHeader.biWidth = width;
    bmi.bmiHeader.biHeight = -height; // top-down
    bmi.bmiHeader.biPlanes = 1;
    bmi.bmiHeader.biBitCount = 32;
    bmi.bmiHeader.biCompression = BI_RGB;

    HDC hdc = GetDC(NULL);
    BYTE* pixels = NULL;
    HBITMAP hDIB = CreateDIBSection(hdc, &bmi, DIB_RGB_COLORS, (void**)&pixels, NULL, 0);
    if (!hDIB) {
        ReleaseDC(NULL, hdc);
        DeleteObject(iconInfo.hbmColor);
        DeleteObject(iconInfo.hbmMask);
        return NULL;
    }

    // Draw the icon's color bitmap into our DIB so we get real pixel data
    HDC hMemDC = CreateCompatibleDC(hdc);
    HBITMAP hOldBmp = (HBITMAP)SelectObject(hMemDC, hDIB);

    HDC hSrcDC = CreateCompatibleDC(hdc);
    HBITMAP hOldSrc = (HBITMAP)SelectObject(hSrcDC, iconInfo.hbmColor);
    BitBlt(hMemDC, 0, 0, width, height, hSrcDC, 0, 0, SRCCOPY);
    SelectObject(hSrcDC, hOldSrc);
    DeleteDC(hSrcDC);

    // Walk every pixel; if it's white (or near-white), make it black
    // Preserve alpha channel so transparency is untouched
    for (int i = 0; i < width * height; i++) {
        BYTE* px = pixels + i * 4; // B, G, R, A
        BYTE b = px[0], g = px[1], r = px[2];

        // Threshold-based "white" check (tune as needed)
        if (r > 240 && g > 240 && b > 240) {
            px[0] = 0; // B
            px[1] = 0; // G
            px[2] = 0; // R
            // px[3] (alpha) left unchanged
        }
    }

    SelectObject(hMemDC, hOldBmp);
    DeleteDC(hMemDC);
    ReleaseDC(NULL, hdc);

    // Build the new icon from modified color bitmap + original mask
    ICONINFO newIconInfo = iconInfo;
    newIconInfo.hbmColor = hDIB;

    HICON hNewIcon = CreateIconIndirect(&newIconInfo);

    DeleteObject(hDIB);
    DeleteObject(iconInfo.hbmColor);
    DeleteObject(iconInfo.hbmMask);

    return hNewIcon;
}